import java.util.Scanner;

public class I {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);

        solve(s.nextInt(), (int)(Double.parseDouble(s.next()) * 10000));
    }


    public static void solve(long n, long p) {
        long studied = 0;
        long notStudied = n;

        long zero;
        long one;
        long two;
        long three;

        long thisP;

        while (true) {
            zero = notStudied * (notStudied - 1) * (notStudied - 2) / 6;
            one = studied * notStudied * (notStudied - 1) / 2;
            two = studied * (studied - 1) * notStudied / 2;
            three = studied * (studied - 1) * (studied - 2) / 6;

            thisP = zero * 0 + one * 1 + two * 2 + three * 2;
            if (thisP * 5000 >= p * n * (n - 1) * (n - 2) / 6) {
                System.out.println(studied);
                return;
            }

            studied++;
            notStudied--;
        }
    }
}
